class Solution {
public:
    long long numberOfPairs(std::vector<int>& nums1, std::vector<int>& nums2, int diff) {
        int n = nums1.size();
        std::vector<int> d(n);
        std::vector<int> all_vals;
        all_vals.reserve(2 * n);
        for (int i = 0; i < n; i++) {
            d[i] = nums1[i] - nums2[i];
            all_vals.push_back(d[i]);
            all_vals.push_back(d[i] + diff);
        }
        std::sort(all_vals.begin(), all_vals.end());
        all_vals.erase(std::unique(all_vals.begin(), all_vals.end()), all_vals.end());

        int m = all_vals.size();
        std::vector<int> bit(m + 2, 0);
        auto add = [&](int idx, int val) {
            for (; idx < (int)bit.size(); idx += idx & (-idx)) bit[idx] += val;
        };
        auto query = [&](int idx) {
            int s = 0;
            for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
            return s;
        };

        auto getIdx = [&](int v) {
            return std::lower_bound(all_vals.begin(), all_vals.end(), v) - all_vals.begin() + 1;
        };

        long long ans = 0;
        for (int x : d) {
            ans += query(getIdx(x + diff));
            add(getIdx(x), 1);
        }
        return ans;
    }
};

class Solution {
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        int[] d = new int[n];
        int[] all = new int[2 * n];
        for (int i = 0; i < n; i++) {
            d[i] = nums1[i] - nums2[i];
            all[2 * i] = d[i];
            all[2 * i + 1] = d[i] + diff;
        }
        java.util.Arrays.sort(all);
        int[] unique = java.util.Arrays.stream(all).distinct().toArray();

        int m = unique.length;
        int[] bit = new int[m + 2];
        long ans = 0;

        for (int x : d) {
            int targetIdx = java.util.Arrays.binarySearch(unique, x + diff) + 1;
            ans += query(bit, targetIdx);
            int xIdx = java.util.Arrays.binarySearch(unique, x) + 1;
            add(bit, xIdx, 1);
        }
        return ans;
    }

    private void add(int[] bit, int idx, int val) {
        for (; idx < bit.length; idx += idx & (-idx)) bit[idx] += val;
    }

    private int query(int[] bit, int idx) {
        int s = 0;
        for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
        return s;
    }
}

var numberOfPairs = function(nums1, nums2, diff) {
    const n = nums1.length;
    const d = new Array(n);
    const all = [];
    for (let i = 0; i < n; i++) {
        d[i] = nums1[i] - nums2[i];
        all.push(d[i], d[i] + diff);
    }
    all.sort((a, b) => a - b);
    const unique = Array.from(new Set(all));

    const m = unique.length;
    const bit = new Array(m + 2).fill(0);
    function add(idx, val) {
        for (; idx < bit.length; idx += idx & (-idx)) bit[idx] += val;
    }
    function query(idx) {
        let s = 0;
        for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
        return s;
    }

    function bsearch(v) {
        let l = 0, r = unique.length - 1;
        while (l <= r) {
            const mid = (l + r) >> 1;
            if (unique[mid] === v) return mid + 1;
            if (unique[mid] < v) l = mid + 1;
            else r = mid - 1;
        }
        return l + 1;
    }

    let ans = 0;
    for (const x of d) {
        ans += query(bsearch(x + diff));
        add(bsearch(x), 1);
    }
    return ans;
};
